-- Six SAMPLE partners for the home page's "Our Partners", with their
-- placeholder logos (400 x 400 px PNG), so the website and the console show
-- the same thing from the start. The names are fictional: replace or delete
-- them under Website -> Our Partners once the firm adds its own.

INSERT INTO "Partner" ("id", "name", "website", "logoData", "logoType", "logoUpdatedAt", "published", "sortOrder", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'Godavari Infra Projects', NULL, decode('', 'hex'), 'image/png', CURRENT_TIMESTAMP, true, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM "Partner" WHERE "name" = 'Godavari Infra Projects');

